import{_ as r,c as l,o as e,ag as d}from"./chunks/framework.Bkod66qp.js";const b=JSON.parse('{"title":"직무관련 범죄 고발 내규","description":"","frontmatter":{"title":"직무관련 범죄 고발 내규","subtitle":"","doc_id":"","last_update":"2014-06-20","author":"","categories":[],"tags":[]},"headers":[],"relativePath":"regulation/907_직무관련 범죄 고발 내규(140620).md","filePath":"regulation/907_직무관련 범죄 고발 내규(140620).md"}'),o={name:"regulation/907_직무관련 범죄 고발 내규(140620).md"};function i(p,t,a,s,n,x){return e(),l("div",null,t[0]||(t[0]=[d(`<h1 id="law-title" class="center" tabindex="-1">직무관련 범죄 고발 내규 <a class="header-anchor" href="#law-title" aria-label="Permalink to &quot;직무관련 범죄 고발 내규 {#law-title .center}&quot;">​</a></h1><div style="text-align:right;"><pre style="display:inline-block;margin:0;white-space:pre;font-family:monospace;">제정 2013.  10.  30
개정 2014.   6.  20</pre></div><h2 id="제1장-총-칙" tabindex="-1">제1장 총 칙 <a class="header-anchor" href="#제1장-총-칙" aria-label="Permalink to &quot;제1장 총 칙&quot;">​</a></h2><h2 id="article1" class="sr-only" tabindex="-1">제1조 (목적) <a class="header-anchor" href="#article1" aria-label="Permalink to &quot;제1조 (목적) {#article1 .sr-only}&quot;">​</a></h2><p><strong>제1조(목적)</strong> 이 내규는 서울문화재단(이하 “재단”이라 한다) 임ㆍ직원이 직무와 관련하여 범죄행위를 행한 경우에 고발대상과 절차 등을 정하여 이행함으로써 깨끗한 조직문화를 만드는데 기여함을 목적으로 한다.</p><h2 id="article2" class="sr-only" tabindex="-1">제2조 (적용범위) <a class="header-anchor" href="#article2" aria-label="Permalink to &quot;제2조 (적용범위) {#article2 .sr-only}&quot;">​</a></h2><p><strong>제2조(적용범위)</strong> 이 내규는 서울문화재단 소속 임ㆍ직원(재직 중 부패와 관련된 퇴직자, 공무수행사인 및 민간심의위원 포함)에게 적용한다.</p><h2 id="article3" class="sr-only" tabindex="-1">제3조 (고발대상) <a class="header-anchor" href="#article3" aria-label="Permalink to &quot;제3조 (고발대상) {#article3 .sr-only}&quot;">​</a></h2><p><strong>제3조(고발대상)</strong> 고발대상은 소속 임ㆍ직원이 직무와 관련하여&quot;형법&quot;, &quot;특정범죄 가중처벌&quot; 등에 관한 법률, 그 밖에 개별 법률의 금지 또는 의무규정을 위반한 범죄행위를 포함한다.</p><h2 id="article4" class="sr-only" tabindex="-1">제4조 (고발주체) <a class="header-anchor" href="#article4" aria-label="Permalink to &quot;제4조 (고발주체) {#article4 .sr-only}&quot;">​</a></h2><p><strong>제4조(고발주체)</strong> ① 각 부서 책임자와 감사담당자는 그 직무를 수행함에 있어 소속 직원의 범죄혐의 사실을 발견한 경우에는 즉시 대표이사에게 보고하여야 한다.<br> ② 대표이사는 제3조에 따른 범죄혐의 사실을 발견하거나 보고받은 경우에는 형사소송법 제234조(고발)에 따라 고발하여야 한다.</p><h2 id="article5" class="sr-only" tabindex="-1">제5조 (고발기준) <a class="header-anchor" href="#article5" aria-label="Permalink to &quot;제5조 (고발기준) {#article5 .sr-only}&quot;">​</a></h2><p><strong>제5조(고발기준)</strong> ① 대표이사가 범죄의 고발여부를 결정함에 있어 그 범죄행위의 경중과 고의 또는 과실여부를 고려하여 판단하되, 특히 각호에 해당하는 경우에는 더욱 엄정히 처리하여야 한다.<br> 1.직무와 관련하여 금품을 수수한 경우<br> 2.공금횡령 등 직무와 관련한 부당한 이득 또는 재물취득과 관련된 범죄에 해당되는 경우<br> 3.부당한 행정행위를 수반한 범죄를 저질러 본인 또는 제3자에게 이익을 가져다 준 경우<br> 4.범죄내용의 파급 개연성이 크고 수사 시 비위 규모가 더 밝혀질 수 있다고 판단되는 경우<br> 5.징계처분을 받고 징계기록 말소기간 이내에 다시 범죄에 해당하는 비위를 행한 경우<br> 6.그 밖에 범죄의 내용, 횟수, 수법 등을 고려할 때 고발하는 것이 타당하다고 판단되는 경우<br> ②제1항 제1호 및 제2호 중 다음 각 호의 어느 하나에 해당하는 경우에는 반드시 고발하여야 한다.<br> 1.횡령금액이 누계금액 100만원 이상인 경우<br> 2. 공금횡령 금액을 전액 원상회복하지 않은 경우<br> 3.최근 3년 이내에 횡령으로 징계를 받은 자가 또다시 횡령을 한 경우<br> 4.금품 · 향응수수 금액이 별표 1에 해당하는 경우</p><h2 id="article6" class="sr-only" tabindex="-1">제6조 (고발 시기 및 절차) <a class="header-anchor" href="#article6" aria-label="Permalink to &quot;제6조 (고발 시기 및 절차) {#article6 .sr-only}&quot;">​</a></h2><p><strong>제6조(고발 시기 및 절차)</strong> ① 고발의 시기는 범죄행위 사실을 확인한 즉시 고발함을 원칙으로 한다. 이 경우 ‘범죄행위 사실을 확인한 즉시’라 함은 횡령혐의자가 횡령사실 및 횡령 금액 등에 대하여 시인한 경우를 말한다.<br> ② 범죄행위자가 사실관계를 부인하는 경우라도 조사결과 증빙자료에 따라 횡령혐의가 명백하다고 판단할 충분한 사유가 있을 경우에도 고발한다.<br> ③ 고발은 대표이사 명의로 고발장을 작성하여 관할 수사기관의 장에게 제출하여야 한다. 다만, 범죄혐의자가 도주 또는 증거인멸의 우려가 있는 경우에는 구두로 고발한 후 고발장을 제출할 수 있다.</p><h2 id="article7" class="sr-only" tabindex="-1">제7조 (고발처리상황 관리) <a class="header-anchor" href="#article7" aria-label="Permalink to &quot;제7조 (고발처리상황 관리) {#article7 .sr-only}&quot;">​</a></h2><p><strong>제7조(고발처리상황 관리)</strong> 대표이사는 고발한 범죄혐의사실의 요지 및 처리내용 등 고발처리상황을 별지 제1호서식에 따라 작성한 후 문서로 유지ㆍ관리하여야 하며, 고발을 하지 아니한 경우에도 범죄행위 사실의 요지와 고발하지 아니하는 사유를 【별지 제2호 서식】에 따라 기록하여 관리하여야 한다.</p><h2 id="article8" class="sr-only" tabindex="-1">제8조 (고발대상사건 묵인행위에 대한 조치) <a class="header-anchor" href="#article8" aria-label="Permalink to &quot;제8조 (고발대상사건 묵인행위에 대한 조치) {#article8 .sr-only}&quot;">​</a></h2><p><strong>제8조(고발대상사건 묵인행위에 대한 조치)</strong> 대표이사는 범죄행위의 보고 의무가 있는 자가 고발대상 범죄행위를 발견하고도 정당한 사유없이 보고하지 아니하고 이를 묵인한 때에는 직무를 태만히 한 것으로 보아 &quot;징계절차 및 양정등에관한 내규&quot;에 따라 징계 등의 조치를 할 수 있다.</p><h2 id="addendum1" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum1" aria-label="Permalink to &quot;부칙 {#addendum1 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2013. 10. 30.&gt;<br> 이 내규는 대표이사의 승인을 득한 날로부터 시행한다.</p><h2 id="addendum2" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum2" aria-label="Permalink to &quot;부칙 {#addendum2 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2014. 6. 20.&gt;<br> 이 내규는 대표이사의 승인을 득한 날로부터 시행한다.</p><p><strong>[별표 1]</strong> &lt;개정 2014. 6. 20.&gt;</p><p>금품 · 향응수수 관련 고발 기준</p><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:fixed;"><colgroup><col style="width:506px;"><col style="width:129px;"></colgroup><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;background-color:#D6D6D6;"><p style="margin:0;text-align:center;">유 형</p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;background-color:#D6D6D6;"><p style="margin:0;text-align:center;">금액기준</p></th></tr><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">직무와 관련한 금품 또는 향응 수수</p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">200만원</p></th></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">직무와 관련한 금품 또는 향응을 요구하여 수수한 경우</p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">100만원</p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">직무와 관련한 금품 또는 향응을 수수하고 수사 시 비위행위 규모가 더 밝혀 질 수 있다고 판단되는 경우</p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">100만원</p></td></tr></table><p><strong>[별지 제1호]</strong></p><p><strong>고발처리 대장</strong></p><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:auto;"><tr><th rowspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">일련</p><p style="margin:0;text-align:left;">번호</p></th><th rowspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">건명 및 범죄 혐의 요지</p></th><th colspan="3" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">피고발자</p></th><th rowspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">고발</p><p style="margin:0;text-align:left;">일시</p></th><th rowspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">고발장</p><p style="margin:0;text-align:left;">접 수</p><p style="margin:0;text-align:left;">기관명</p></th><th rowspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">수사개시 진행상황 등 공소제기 상정</p></th><th rowspan="2" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">기타참고사항</p><p style="margin:0;text-align:left;">(고발유예 사유 등)</p></th></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">소속</p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">직급</p><p style="margin:0;text-align:left;">(직위)</p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">성명</p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;"></p></td></tr></table>`,29)]))}const m=r(o,[["render",i]]);export{b as __pageData,m as default};
